'use strict';
const TERRAIN_ROCKS=[];   // the little rocks around camp (see the loop near Big Thumb); models replace them in 23-models.js
/* public/js/15-terrain.js -- dug holes, buried-loot seeding, streaming terrain chunks (near/far detail levels). Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- holes ---------- */
const holes=[];const grid=new Map();
const gkey=(cx,cz)=>(cx+64)*512+(cz+64);
const cellOf=v=>Math.floor((v+HALF)/CELL);
function addHole(h){
  const a=hash2(Math.round(h.x*10)+7,Math.round(h.z*10)-3)*Math.PI*2;
  h.r=h.r||HOLE_R;h.mx=h.x+Math.cos(a)*(h.r+1.0);h.mz=h.z+Math.sin(a)*(h.r+1.0);
  holes.push(h);const k=gkey(cellOf(h.x),cellOf(h.z));let L=grid.get(k);if(!L){L=[];grid.set(k,L)}L.push(h);return h;
}
function forNearHoles(x,z,fn){const cx=cellOf(x),cz=cellOf(z);for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){const L=grid.get(gkey(cx+i,cz+j));if(L)for(const h of L)fn(h)}}
/* skip (optional): holes whose dug-out bowl to leave out -- their spoil mound still counts. The hole liners use
   it to draw one hole's own bowl and let a shader decide where a deeper neighbour takes over (46-holes.js). */
function surfaceAt(x,z,b,skip){
  let dep=0,mound=0;
  forNearHoles(x,z,h=>{
    if(h.d<=0)return;
    const dx=x-h.x,dz=z-h.z,d2=dx*dx+dz*dz;
    if(d2<h.r*h.r&&!(skip&&skip(h))){const t=Math.sqrt(d2)/h.r;const p=t<0.72?1:1-sm((t-0.72)/0.28);const v=h.d*p;if(v>dep)dep=v}
    if(!h.noMound){const ex=x-h.mx,ez=z-h.mz,e2=ex*ex+ez*ez;if(e2<MR*MR){const t=Math.sqrt(e2)/MR;mound+=Math.min(h.d,FIVE_FT)*0.3*(0.5+0.5*Math.cos(Math.PI*t))}}
  });
  return dep>0.001?b-dep:b+mound;
}
function holeNear(x,z,maxDist){let best=null,bd=maxDist*maxDist;forNearHoles(x,z,h=>{const dx=x-h.x,dz=z-h.z,d2=dx*dx+dz*dz;if(d2<bd){bd=d2;best=h}});return best}

/* pre-dug holes from a hundred years of campers */
const preHoles=[];
for(let k=0;k<40000&&preHoles.length<3000;k++){
  const a=rng()*Math.PI*2,dd=Math.pow(rng(),1.6)*EDGE*1.35,x=r1(Math.cos(a)*dd),z=r1(20+Math.sin(a)*dd);
  if(Math.max(Math.abs(x),Math.abs(z))>EDGE-8||inCamp(x,z)||nearCampZone(x,z)||(z>12&&z<70&&Math.abs(x)<30))continue;
  if(holeNear(x,z,3.4))continue;
  preHoles.push(addHole({x,z,d:FIVE_FT,pre:true}));
}

/* ---------- buried things ---------- */
const LOOT={
  cap:{name:'Bottle cap',val:4,color:0xb8b8b8},
  can:{name:'Rusty can',val:6,color:0x8a4b2a},
  spoon:{name:'Old spoon',val:9,color:0xd0d0d0},
  shoe:{name:'Horseshoe',val:12,color:0x5f5f5f},
  arrow:{name:'Arrowhead',val:16,color:0x4a4038},
  jar:{name:'Jar of spiced peaches',val:22,color:0xd98a3a},
  fossil:{name:'Fossil fish',val:30,color:0xd8ccb0},
  lipstick:{name:'Silver lipstick tube',val:40,color:0xe0e0e8},
  sploosh:{name:'Old jar of Sploosh',val:48,color:0xe8a040},
  locket:{name:'Gold locket',val:60,color:0xd4af37},
  pistol:{name:'Kate\'s old pistol',val:75,color:0x2a2a2a},
  safe:{name:'Old iron safe',val:120,color:0x3b3f45,heavy:true},
  strongbox:{name:'Kate\'s strongbox',val:80,color:0x5b3a1e,heavy:true},
  kb:{name:'Gold tube marked "KB"',val:0,color:0xd4af37,key:true},
  suitcase:{name:'Suitcase marked "STANLEY YELNATS"',val:500,color:0x6b3e1f,key:true}
};
const WEIGHTS=[['cap',30],['can',24],['spoon',14],['shoe',12],['arrow',9],['jar',6],['fossil',5],['lipstick',2],['sploosh',1.6],['locket',1.2],['pistol',0.8]];
const WSUM=WEIGHTS.reduce((s,w)=>s+w[1],0);
/* farther from camp, the rarer finds get more common */
function pickType(f){const w=WEIGHTS.map(([k,v],i)=>[k,v*(1+f*i*0.9)]);let r=rng()*w.reduce((s,e)=>s+e[1],0);for(const[k,v]of w){if((r-=v)<0)return k}return 'cap'}
/* spots spread out around camp: dense close in, thinner (but richer) far out */
function spotAround(minD,maxD,pw,minPre){for(let k=0;k<400;k++){const a=rng()*Math.PI*2,d=minD+(maxD-minD)*Math.pow(rng(),pw);const x=Math.cos(a)*d,z=20+Math.sin(a)*d;if(Math.max(Math.abs(x),Math.abs(z))>EDGE-6||nearCampZone(x,z))continue;if(holeNear(x,z,minPre))continue;return{x,z}}return{x:-80,z:-80}}
const items=[];
for(let i=0;i<5000;i++){const p=spotAround(14,EDGE*1.35,1.35,1.7);items.push({id:i,type:pickType(clamp(Math.hypot(p.x,p.z-20)/450,0,1)),x:p.x,z:p.z,depth:0.3+rng()*1.15,found:false})}
{const p=spotAround(120,320,1,2.5);items.push({id:items.length,type:'kb',x:p.x,z:p.z,depth:1.2,found:false})}
let SUITCASE;
{const p=spotAround(220,480,1,2.8);SUITCASE={id:items.length,type:'suitcase',x:p.x,z:p.z,depth:2.3,found:false};items.push(SUITCASE)}
const SEARCH={x:SUITCASE.x+(rng()-0.5)*9,z:SUITCASE.z+(rng()-0.5)*9,r:10};
/* heavy finds, buried deeper than a plain shovel reaches (you need the long-handled shovel) */
for(let i=0;i<220;i++){const p=spotAround(40,EDGE*1.3,1.1,2.2);items.push({id:items.length,type:rng()<0.4?'safe':'strongbox',x:p.x,z:p.z,depth:1.6+rng()*0.9,found:false})}

/* ---------- terrain: detailed chunks stream in around you; one coarse mesh covers the distance ---------- */
/* PERF: level of detail. Chunks within NEAR_R of the player are built at full detail (a point every RES = 0.4 m).
   Chunks farther out, up to LOAD_R, are built at 1/COARSE_STEP of that (a point every 1.2 m): 9x fewer triangles,
   but holes and dirt piles still show. Before this, every chunk out to ~170 m was full detail (~660k triangles). */
const CH=24, CN=Math.round(CH/RES), LOAD_R=100, NEAR_R=40, COARSE_STEP=3;
const C_SAND=new T.Color(0xdcab6e),C_SAND2=new T.Color(0xc99558),C_CRACK=new T.Color(0xa87444),C_DEEP=new T.Color(0x6e3c20),C_DIRT=new T.Color(0xc99a64),C_CAMP=new T.Color(0xc4955f),tmpC=new T.Color();
function toneAt(x,z){const crack=Math.abs(vnoise(x*0.55+40,z*0.55)-0.5)<0.035?1:0;return clamp(vnoise(x*0.18,z*0.18)*0.9+crack*2,0,3)}
function shade(col,i,x,z,b,h,tn){
  if(tn>1.5)tmpC.copy(C_SAND).lerp(C_CRACK,0.55);else tmpC.copy(C_SAND).lerp(C_SAND2,tn);
  if(ZONE_TINT)ZONE_TINT(tmpC,x,z,b,tn);   // another map's own ground colours (88-zones.js)
  else if(inCamp(x,z))tmpC.lerp(C_CAMP,0.5);
  if(h<b-0.02)tmpC.lerp(C_DEEP,0.25+0.7*clamp((b-h)/1.8,0,1));
  else if(h>b+0.02)tmpC.lerp(C_DIRT,clamp((h-b)/0.35,0,1)*0.85);
  col[i*3]=tmpC.r;col[i*3+1]=tmpC.g;col[i*3+2]=tmpC.b;
}
const chunks=new Map(),chunkMat=new T.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:1,metalness:0});
const ckey=(i,j)=>(i+100)*1000+(j+100);
/* st = 1 for a full-detail chunk, COARSE_STEP for a coarse one. Each chunk remembers its own grid (C.cn cells
   per side, C.res metres per cell), so everything that reads chunk data works with either detail level. */
function buildChunk(i,j,st){
  st=st||1;const old=chunks.get(ckey(i,j));if(old){scene.remove(old.m);old.g.dispose()}   // replacing a chunk at another detail level
  const cn=CN/st,res=RES*st,x0=i*CH,z0=j*CH,n=cn+1,g=new T.PlaneGeometry(CH,CH,cn,cn);g.rotateX(-Math.PI/2);g.translate(x0+CH/2,0,z0+CH/2);
  const pos=g.attributes.position,base=new Float32Array(n*n),hts=new Float32Array(n*n),tone=new Float32Array(n*n),col=new Float32Array(n*n*3);
  for(let r=0;r<n;r++)for(let c=0;c<n;c++){const k=r*n+c,x=x0+c*res,z=z0+r*res,b=baseH(x,z),h=surfaceAt(x,z,b);base[k]=b;tone[k]=toneAt(x,z);hts[k]=h;pos.setY(k,h);shade(col,k,x,z,b,h,tone[k])}
  g.setAttribute('color',new T.BufferAttribute(col,3));g.computeBoundingSphere();
  const m=new T.Mesh(g,chunkMat);m.receiveShadow=true;scene.add(m);
  const C={x0,z0,st,cn,res,base,hts,tone,col,g,m,dirty:false};chunks.set(ckey(i,j),C);return C;
}
function rebuildRegion(x0,z0,x1,z1){
  for(const C of chunks.values()){
    if(C.x0>x1||C.x0+CH<x0||C.z0>z1||C.z0+CH<z0)continue;
    const cn=C.cn,res=C.res,n=cn+1;
    const c0=clamp(Math.floor((x0-C.x0)/res),0,cn),c1=clamp(Math.ceil((x1-C.x0)/res),0,cn),q0=clamp(Math.floor((z0-C.z0)/res),0,cn),q1=clamp(Math.ceil((z1-C.z0)/res),0,cn),pos=C.g.attributes.position;
    for(let r=q0;r<=q1;r++)for(let c=c0;c<=c1;c++){const k=r*n+c,x=C.x0+c*res,z=C.z0+r*res,h=surfaceAt(x,z,C.base[k]);C.hts[k]=h;pos.setY(k,h);shade(C.col,k,x,z,C.base[k],h,C.tone[k])}
    C.dirty=true;
  }
}
function touchHole(h){const e=h.r+2.4;rebuildRegion(h.x-e,h.z-e,h.x+e,h.z+e)}
function flushTerrain(){for(const C of chunks.values())if(C.dirty){C.dirty=false;C.g.attributes.position.needsUpdate=true;C.g.attributes.color.needsUpdate=true}}
function streamChunks(fx,fz,budget){
  const R=Math.ceil(LOAD_R/CH)+1,ci=Math.floor(fx/CH),cj=Math.floor(fz/CH),want=[];
  for(let i=ci-R;i<=ci+R;i++)for(let j=cj-R;j<=cj+R;j++){
    if(i*CH>=HALF||(i+1)*CH<=-HALF||j*CH>=HALF||(j+1)*CH<=-HALF)continue;
    const d=Math.hypot(i*CH+CH/2-fx,j*CH+CH/2-fz);
    if(d>LOAD_R+CH*0.72)continue;
    /* Pick a detail level. Coarse chunks upgrade as soon as they come within NEAR_R, but full-detail chunks only
       drop back once they're a whole chunk farther out, so walking back and forth doesn't rebuild them over and over. */
    const C=chunks.get(ckey(i,j)),nearD=NEAR_R+CH*0.72;
    const st=d<=nearD?1:C&&C.st===1&&d<=nearD+CH?1:COARSE_STEP;
    if(!C||C.st!==st)want.push([d,i,j,st]);
  }
  if(want.length){want.sort((a,b)=>a[0]-b[0]);const nb=budget||(want[0][0]<NEAR_R*1.2?6:2);for(let k=0;k<Math.min(nb,want.length);k++)buildChunk(want[k][1],want[k][2],want[k][3])}
  // PERF: unload chunks once they're 1.5 chunks past LOAD_R (was 3), so fewer out-of-range chunks sit in the scene.
  for(const[key,C]of chunks)if(Math.hypot(C.x0+CH/2-fx,C.z0+CH/2-fz)>LOAD_R+CH*1.5){scene.remove(C.m);C.g.dispose();chunks.delete(key)}
}
function groundAt(x,z){
  if(Math.max(Math.abs(x),Math.abs(z))>=HALF)return OUTER_Y;
  const C=chunks.get(ckey(Math.floor(x/CH),Math.floor(z/CH)));
  if(!C)return surfaceAt(x,z,baseH(x,z));
  if(C.st!==1)return surfaceAt(x,z,baseH(x,z));   // coarse chunk: compute exactly, so nobody stands on the rougher mesh
  const n=CN+1,fx=(x-C.x0)/RES,fz=(z-C.z0)/RES,c=Math.min(Math.floor(fx),CN-1),r=Math.min(Math.floor(fz),CN-1),tx=fx-c,tz=fz-r,i=r*n+c;
  return lerp(lerp(C.hts[i],C.hts[i+1],tx),lerp(C.hts[i+n],C.hts[i+n+1],tx),tz);
}
/* coarse far terrain, cut away (discarded) wherever the detailed chunks are loaded */
let FAR_TERRAIN=null;   // the lake's coarse far mesh; 88-zones.js hides it while the crew is in another map
const farU={uFocus:{value:new T.Vector2(0,12)},uR:{value:LOAD_R-3}};
{
  const FR=8,FN=Math.round(HALF*2/FR),g=new T.PlaneGeometry(HALF*2,HALF*2,FN,FN);g.rotateX(-Math.PI/2);
  const p=g.attributes.position,col=new Float32Array(p.count*3);
  for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);p.setY(i,baseH(x,z)-0.08);tmpC.copy(C_SAND).lerp(C_SAND2,vnoise(x*0.03,z*0.03));if(inCamp(x,z))tmpC.lerp(C_CAMP,0.5);col[i*3]=tmpC.r;col[i*3+1]=tmpC.g;col[i*3+2]=tmpC.b}
  g.setAttribute('color',new T.BufferAttribute(col,3));
  const mat=new T.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:1,metalness:0});
  mat.onBeforeCompile=sh=>{Object.assign(sh.uniforms,farU);
    sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vFarW;').replace('#include <begin_vertex>','#include <begin_vertex>\nvFarW=(modelMatrix*vec4(transformed,1.0)).xyz;');
    sh.fragmentShader=sh.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vFarW;uniform vec2 uFocus;uniform float uR;').replace('void main() {','void main() {\nif(distance(vFarW.xz,uFocus)<uR)discard;')};
  const far=new T.Mesh(g,mat);far.receiveShadow=true;scene.add(far);FAR_TERRAIN=far;
}
streamChunks(0,12,999);

/* outer desert + mountains + Big Thumb */
let updateThumbHaze;   // assigned inside the block below; declared out here so frame() can call it every frame
const TH_X=185, TH_Z=-1080;   // Big Thumb's position: north side of the lake, off to the side, ~350-480 m past the ±600 edge
                               // (hoisted out of the block below so the landslide code further down can read it too)
{
  const mat=new T.MeshStandardMaterial({color:0xd4a266,flatShading:true,roughness:1});
  const strips=[[0,-HALF-450,HALF*2+1800,900],[0,HALF+450,HALF*2+1800,900],[-HALF-450,0,900,HALF*2],[HALF+450,0,900,HALF*2]];
  for(const[x,z,w,d]of strips){const m=new T.Mesh(new T.PlaneGeometry(w,d),mat);m.rotation.x=-Math.PI/2;m.position.set(x,OUTER_Y-0.02,z);m.receiveShadow=true;scene.add(m)}
  for(let i=0;i<46;i++){
    const a=i/46*Math.PI*2+rng()*0.1,d=HALF+150+rng()*260,h=25+rng()*60,rad=90+rng()*120;
    const m=new T.Mesh(new T.CylinderGeometry(rad*(0.35+rng()*0.3),rad,h,6+Math.floor(rng()*3)),M(rng()<0.5?0xb98a5e:0xa9785a));
    m.position.set(Math.cos(a)*d,OUTER_Y+h/2-2,Math.sin(a)*d);m.rotation.y=rng()*6;scene.add(m);
  }
  /* Big Thumb (God's Thumb, in the book): a huge rock landmark, hundreds of metres tall, well outside the playable
     square so nobody can ever reach it -- just see it from camp and most of the lake. It's a stack of a few cheap
     primitives (scree slope, a rounded "fist" base, banded strata ledges, the thumb shaft, a rounded tip) so it's
     static and cheap forever: no shadows (nothing that big and that far away needs one you'd ever notice). */
  const TH_SCREE_R=250, TH_SCREE_H=42;       // loose scree slope skirting the foot (radius/height, m)
  const TH_BASE_R0=185, TH_BASE_R1=118, TH_BASE_H=95;  // the big rounded mass the thumb rises out of (bottom/top radius, height)
  const TH_LEDGE_H=24, TH_LEDGE_N=4;         // strata ledges stacked above the base: height each, how many
  const TH_SHAFT_R0=44, TH_SHAFT_R1=33, TH_SHAFT_H=175; // the thumb's own vertical column (bottom/top radius, height)
  const TH_TIP_R=38;                          // the rounded tip ("nail") on top
  const TH_TILT=0.05;                         // a small lean, so it doesn't read as a machined cylinder
  const TH_HAZE=0.55;                         // how strongly it blends into the current sky/fog colour -- see thumbMat()
  const thumbMats=[];   // {m,base} pairs refreshed against the current fog colour every frame by updateThumbHaze()
  function thumbMat(hex){
    // Big Thumb sits past the fog's 1000 m range (real THREE.Fog would just swallow it), so its materials skip fog
    // entirely and updateThumbHaze() fakes the same "fades into the haze" look by hand, blending toward whatever
    // colour scene.fog.color currently is -- which already tracks day, dusk, night and the disco party.
    const base=new T.Color(hex);
    const m=new T.MeshStandardMaterial({color:hex,flatShading:true,roughness:1,metalness:0,fog:false});
    thumbMats.push({m,base});return m;
  }
  const thumb=new T.Group();
  const scree=new T.Mesh(new T.ConeGeometry(TH_SCREE_R,TH_SCREE_H,9),thumbMat(0xc7a172));scree.position.y=TH_SCREE_H*0.5;thumb.add(scree);
  let thy=TH_SCREE_H*0.72;
  const thBase=new T.Mesh(new T.CylinderGeometry(TH_BASE_R1,TH_BASE_R0,TH_BASE_H,9),thumbMat(0x8c6d51));thBase.position.y=thy+TH_BASE_H*0.5;thumb.add(thBase);
  thy+=TH_BASE_H;
  const LEDGE_COLORS=[0x9c7a5a,0x876048];   // alternating shades so the stacked ledges read as strata bands
  let ledgeR0=TH_BASE_R1;
  for(let i=0;i<TH_LEDGE_N;i++){
    const r1=lerp(TH_BASE_R1,TH_SHAFT_R0,(i+1)/TH_LEDGE_N);
    const ledge=new T.Mesh(new T.CylinderGeometry(r1,ledgeR0,TH_LEDGE_H,9),thumbMat(LEDGE_COLORS[i%2]));
    ledge.position.y=thy+TH_LEDGE_H*0.5;thumb.add(ledge);thy+=TH_LEDGE_H;ledgeR0=r1;
  }
  const thShaft=new T.Mesh(new T.CylinderGeometry(TH_SHAFT_R1,TH_SHAFT_R0,TH_SHAFT_H,9),thumbMat(0xa9835f));thShaft.position.y=thy+TH_SHAFT_H*0.5;thumb.add(thShaft);
  thy+=TH_SHAFT_H;
  const thTip=new T.Mesh(new T.SphereGeometry(TH_TIP_R,10,7),thumbMat(0xb99269));thTip.scale.y=0.82;thTip.position.y=thy+TH_TIP_R*0.7;thumb.add(thTip);
  thumb.rotation.set(TH_TILT,0.3,TH_TILT*0.6);thumb.position.set(TH_X,OUTER_Y-2,TH_Z);scene.add(thumb);
  updateThumbHaze=()=>{for(const t of thumbMats)t.m.color.copy(t.base).lerp(scene.fog.color,TH_HAZE)};
  for(let i=0;i<30;i++){
    const x=(rng()*2-1)*54,z=(rng()*2-1)*54;if(inCamp(x,z))continue;
    const rock=new T.Mesh(new T.DodecahedronGeometry(0.3+rng()*0.5,0),M(0x9c7552));
    rock.position.set(x,baseH(x,z)+0.1,z);rock.rotation.set(rng()*3,rng()*3,0);rock.castShadow=true;scene.add(rock);
    TERRAIN_ROCKS.push({m:rock,x,y:baseH(x,z),z,ry:rock.rotation.y,size:rock.geometry.parameters.radius});   // 23-models.js swaps in Blender rocks
  }
}

